"""Minimal owner route and one-source separate agreement/TZ PDFs; synthetic only."""
import copy,json,os,secrets
from playwright.sync_api import sync_playwright,expect
import test_contract_package as package
class SimplePreparation(package.ContractPackage):
 def test_pair_validates_both_before_creation_and_replays_without_duplicate_documents(self):
  oid,legacy,g,v,terms=self.new_documents();before=self.f.sql('SELECT COUNT(*) n FROM nd_lc_document_bindings')[0]['n'];bad=copy.deepcopy(v);bad['spec.date']='';r=self.ctp('terms',order_id=oid,proposal_id=int(legacy[0]['id']),values=bad,approved=True,confirm_terms=True);bad_terms=r.json()['id'];r=self.ctp('generate-pair',template_ids=[int(t['id']) for t in self.templates[:2]],terms_id=bad_terms);self.assertEqual(r.status_code,422,r.text);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_lc_document_bindings')[0]['n'],before)
  payload={'template_ids':[int(t['id']) for t in self.templates[:2]],'terms_id':terms,'request_key':secrets.token_hex(32)};r=self.ctp('generate-pair',**payload);self.assertEqual(r.status_code,200,r.text);docs=r.json()['documents'];self.assertEqual({d['kind'] for d in docs},{'agreement','specification'});again=self.ctp('generate-pair',**payload);self.assertEqual(again.status_code,200,again.text);self.assertEqual(docs,again.json()['documents']);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_lc_document_bindings')[0]['n'],before+2)
  for d in docs:
   self.assertEqual(self.lg('documents/'+str(d['id'])).json()['record']['state'],'OWNER_REVIEW');pdf=self.owner.get(self.base+'/lifecycle-api.php?mode=owner&r=documents/'+str(d['id'])+'/pdf');self.assertEqual(pdf.status_code,200);self.assertTrue(pdf.content.startswith(b'%PDF-'));self.assertIsNone(self.f.sql('SELECT owner_reviewed_at FROM nd_lc_pdf_assets WHERE binding_id=?',params=[d['id']])[0]['owner_reviewed_at'])
  self.assertIn(self.customer.post(self.base+'/lifecycle-api.php?r=contracts/generate-pair',json=payload).status_code,[401,403,503])
 def test_workspace_restores_current_order_terms_shows_only_essential_fields_and_prepares_pair(self):
  oid,legacy,g,v,terms=self.new_documents()
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);context=browser.new_context(viewport={'width':375,'height':812});context.add_cookies([{'name':c.name,'value':c.value,'url':self.base} for c in self.owner.cookies]);page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(self.base+'/order-workflow.php?order='+str(oid)+'&stage=contract');expect(page.locator('body')).to_have_attribute('data-workflow-ready','true');button=page.get_by_role('button',name='Подготовить договор и ТЗ',exact=True);button.wait_for();form=page.locator('form').filter(has=button);expect(form).to_contain_text('Условия подставлены');self.assertEqual(page.locator('[data-contract-field="project.name"]').input_value(),v['project.name']);self.assertLessEqual(form.locator('[data-contract-field]:visible').count(),8);self.assertEqual(page.locator('#workflow-progress li').count(),8);self.assertFalse(page.evaluate('document.documentElement.scrollWidth>innerWidth'));self.assertEqual(page.locator('#workflow-progress').get_by_role('button',name='Расчёт',include_hidden=True).count(),0);page.locator('form').filter(has=button).evaluate('(f)=>f.scrollIntoView({block:"start"})');page.screenshot(path='/tmp/neuro-simple-order-mobile.png',full_page=False);page.set_viewport_size({'width':1440,'height':1000});page.screenshot(path='/tmp/neuro-simple-order-desktop.png',full_page=False);page.set_viewport_size({'width':375,'height':812})
   form.get_by_role('checkbox',name='Я проверил соответствие всех условий',exact=False).check();form.get_by_role('button',name='Добавить сценарий',exact=True).click();button.click();feedback=form.locator('[data-form-feedback]');expect(feedback).to_contain_text('Проверьте все отмеченные поля');self.assertEqual(feedback.get_by_role('button').count(),2);criteria=form.locator('fieldset').filter(has=page.locator('legend',has_text='Сценарий 2'));criteria.get_by_label('Действия пользователя',exact=True).fill('Открыть второй проверяемый экран');criteria.get_by_label('Наблюдаемый результат',exact=True).fill('Экран доступен и содержит согласованный текст');button.click();page.wait_for_function('() => location.search.includes("stage=signatures") || Array.from(document.querySelectorAll("[data-form-feedback]")).some(e=>!e.hidden && e.textContent && !e.textContent.includes("Выполняется"))');self.assertIn('stage=signatures',page.url,page.locator('[data-form-feedback]:visible').all_text_contents());page.wait_for_url('**stage=signatures**');self.assertEqual(len(page.context.pages),1);self.assertEqual(self.f.sql("SELECT COUNT(*) n FROM nd_lc_document_bindings b JOIN nd_lc_pdf_assets a ON a.binding_id=b.id WHERE b.order_id=?",params=[oid])[0]['n'],2);self.assertEqual(errors,[]);browser.close()
 def test_price_words_are_derived_without_owner_typing(self):
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=browser.new_page();page.goto(self.base+'/contract-settings.php');page.wait_for_function('() => Boolean(window.ndContractEssentials)')
   for amount,expected in [('0.00','Ноль рублей 00 копеек'),('1.01','Один рубль 01 копейка'),('2.02','Два рубля 02 копейки'),('11.11','Одиннадцать рублей 11 копеек'),('1899.68','Одна тысяча восемьсот девяносто девять рублей 68 копеек'),('21000.00','Двадцать одна тысяча рублей 00 копеек'),('1000000.00','Один миллион рублей 00 копеек')]:self.assertEqual(page.evaluate('(v)=>ndContractEssentials.moneyWords(v)',amount),expected)
   browser.close()
 def test_known_answers_fill_empty_terms_without_overwriting_identity_dates_or_order_context(self):
  oid,legacy,g,v,terms=self.new_documents()
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=browser.new_page();page.goto(self.base+'/contract-settings.php');page.wait_for_function('() => Boolean(window.ndContractEssentials)');result=page.evaluate('''() => {const r={context:{order_id:12,label:'ND-12 — Test'},flow:{proposal_binding_id:14},lists:{documents:[]}},templates=[{id:1,kind:'agreement',state:'APPROVED'},{id:2,kind:'specification',state:'APPROVED'}],s={owner:null,terms:[{id:99,order_id:13,data_json:JSON.stringify({values:{'project.name':'WRONG ORDER'},proposal_id:99})},{id:5,order_id:12,data_json:JSON.stringify({values:{'project.name':'','contract.date':'','spec.functions':'','support.duration':''},proposal_id:14,legacy_fields:{deliverables:'EXACT SAVED RESULT',support_terms:'Поддержка не включена.'}})}]};const p=ndContractEssentials.prepare(s,r,templates);ndContractEssentials.fillMetadata(p.values,r.context);return p;}''');self.assertEqual(result['values']['project.name'],'');self.assertEqual(result['values']['contract.date'],'');self.assertEqual(result['values']['spec.functions'],'EXACT SAVED RESULT');self.assertIn('поддержка после передачи не включена',result['values']['support.duration']);self.assertEqual(result['values']['contract.number'],'ND-12');self.assertEqual(result['term']['id'],5);self.assertEqual(result['proposal'],14);browser.close()
for name in dir(package.ContractPackage):
 if name.startswith('test_'):setattr(SimplePreparation,name,None)
